217	    /**
218	     * 召回：RELEASED 或 SPLIT 批次可召回，召回后进入 RECALLED 并不再出现在可用批次查询中。
219	     * 召回提交后其全部后代立即不可用（排除出可用查询、禁止新增检验/批准/拆分），
220	     * 但后代自身状态与既有检验、批准记录不改写，也不为后代补写召回记录。
221	     */
222	    public StoredResponse recall(String batchKey, String actorId, RecallRequest req) {
223	        if (actorId == null || actorId.isBlank()) {
224	            throw ApiException.badRequest("X-Actor-Id 不能为空");
225	        }
226	        String actor = actorId.trim();
227	        String fingerprint = fingerprint("recall", batchKey, actor, req.reason());
228	        return executeIdempotent(CMD_RECALL, req.commandKey(), fingerprint, () -> {
229	            // 先做不加锁的存在性与状态预判
230	            BatchRepository.BatchRow preview = repo.findBatch(batchKey)
231	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
232	            BatchStatus previewStatus = BatchStatus.valueOf(preview.status());
233	            if (previewStatus != BatchStatus.RELEASED && previewStatus != BatchStatus.SPLIT
234	                    && previewStatus != BatchStatus.MERGED) {
235	                throw ApiException.conflict("批次状态 " + previewStatus
236	                        + " 不允许召回，仅 RELEASED、SPLIT 或 MERGED 可召回");
237	            }
238	            // 逐行锁定自身与全部后代（合并为一个集合后按业务键排序，保证锁顺序全局确定）：
239	            // 与后代上的检验/批准/拆分/合批互斥，避免与合批的排序父批锁形成环；
240	            // 按事务提交顺序裁决——召回先提交则后代新操作看到召回并返回 422。
241	            Set<String> lockedKeys = new HashSet<>(loadGraph().descendantKeys(batchKey));
242	            lockedKeys.add(batchKey);
243	            List<String> orderedKeys = new ArrayList<>(lockedKeys);
244	            Collections.sort(orderedKeys);
245	            for (String lockedKey : orderedKeys) {
246	                repo.findBatchForUpdate(lockedKey);
247	            }
248	            // 锁齐后在锁内重查命令快照：并发同键召回在锁等待期间可能已由对方提交
249	            var loggedAfterLock = loggedResponse(CMD_RECALL, req.commandKey(), fingerprint);
250	            if (loggedAfterLock.isPresent()) {
251	                return loggedAfterLock.get();
252	            }
253	            // 锁等待期间状态可能已被并发事务改写，锁内复核
254	            BatchRepository.BatchRow batch = repo.findBatchForUpdate(batchKey)
255	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
256	            BatchStatus status = BatchStatus.valueOf(batch.status());
257	            if (status != BatchStatus.RELEASED && status != BatchStatus.SPLIT
258	                    && status != BatchStatus.MERGED) {
259	                throw ApiException.conflict("批次状态 " + status
260	                        + " 不允许召回，仅 RELEASED、SPLIT 或 MERGED 可召回");
261	            }
262	            String now = now();
263	            repo.insertRecall(new BatchRepository.RecallRow(0L, batchKey, req.commandKey(),
264	                    actor, req.reason(), now));
265	            repo.updateStatus(batchKey, BatchStatus.RECALLED.name());
266	            RecallResponse body = new RecallResponse(batchKey, actor, req.reason(),
267	                    BatchStatus.RECALLED, Instant.parse(now));
268	            return new StoredResponse(201, toJson(body));
269	        });
270	    }
