272	    /**
273	     * 当前可用批次：排除已召回（RECALLED）、已拆分（SPLIT）批次，
274	     * 以及任一祖先被召回的后代批次；后代自身状态不改写。
275	     */
276	    public List<BatchResponse> listAvailable() {
277	        LineageGraph graph = loadGraph();
278	        Set<String> recalled = new HashSet<>(repo.findRecalledKeys());
279	        return repo.findAvailableBatches().stream()
280	                .filter(b -> !BatchStatus.SPLIT.name().equals(b.status()))
281	                .filter(b -> !BatchStatus.MERGED.name().equals(b.status()))
282	                .filter(b -> graph.recalledAncestors(b.batchKey(), recalled).isEmpty())
283	                .map(this::toBatchResponse)
284	                .toList();
285	    }
286	
287	    /**
288	     * 批次完整历史：批次概要 + 全部检验 + 全部批准 + 召回记录，历史不因召回而删除或改写。
289	     */
290	    public BatchHistoryResponse history(String batchKey) {
291	        BatchRepository.BatchRow batch = repo.findBatch(batchKey)
292	                .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
293	        List<String> required = repo.findRequiredTests(batchKey);
294	        List<BatchRepository.TestRow> testRows = repo.findTests(batchKey);
295	        // 按提交顺序推导每条检验结果落定后的批次状态快照：FAIL→REJECTED；
296	        // 必做项全部 PASS 时该条→PENDING_RELEASE；其余→QUARANTINED。
297	        List<TestResultResponse> tests = new java.util.ArrayList<>(testRows.size());
298	        for (BatchRepository.TestRow t : testRows) {
299	            tests.add(toTestResponse(t, snapshotAfter(t, testRows, required).name()));
300	        }
301	        List<ApprovalResponse> approvals = repo.findApprovals(batchKey).stream()
302	                .map(a -> {
303	                    // 历史快照：第一笔批准落定 RELEASE_REVIEW，第二笔落定 RELEASED；不随后续召回改写
304	                    BatchStatus snapshot = a.seq() == 1
305	                            ? BatchStatus.RELEASE_REVIEW
306	                            : BatchStatus.RELEASED;
307	                    return new ApprovalResponse(a.batchKey(), a.actorId(), ApprovalRole.valueOf(a.role()),
308	                            a.seq(), snapshot, Instant.parse(a.createdAt()));
309	                })
310	                .toList();
311	        RecallResponse recall = repo.findRecall(batchKey)
312	                .map(r -> new RecallResponse(r.batchKey(), r.actorId(), r.reason(),
313	                        BatchStatus.RECALLED, Instant.parse(r.createdAt())))
314	                .orElse(null);
315	        return new BatchHistoryResponse(toBatchResponse(batch), tests, approvals, recall);
316	    }
317	
318	    /**
319	     * 幂等执行：同事务内先查 command_log，命中则按指纹返回快照或 409；
320	     * 未命中执行业务动作并写入快照。并发同键插入冲突时重试，读取已提交结果。
321	     */
